select jsonb_build_object(
'captured_at',current_timestamp,'postgres_version',current_setting('server_version'),
'project','xjnukuerzlrxjjqwmgkn',
'schema', (select jsonb_build_object('name',nspname,'owner',pg_get_userbyid(nspowner),'acl',nspacl) from pg_namespace where nspname='synapse'),
'roles',(select jsonb_agg(jsonb_build_object('name',rolname,'inherit',rolinherit,'login',rolcanlogin,'bypassrls',rolbypassrls)) from pg_roles where rolname like 'synapse%'),
'tables',(select jsonb_agg(jsonb_build_object('name',c.relname,'owner',pg_get_userbyid(c.relowner),'rls',c.relrowsecurity,'force_rls',c.relforcerowsecurity,'options',c.reloptions,'columns',(select jsonb_agg(jsonb_build_object('name',a.attname,'type',format_type(a.atttypid,a.atttypmod),'not_null',a.attnotnull,'identity',a.attidentity,'generated',a.attgenerated,'expression',pg_get_expr(d.adbin,d.adrelid),'collation',case when a.attcollation<>t.typcollation then a.attcollation::regcollation::text end) order by a.attnum) from pg_attribute a join pg_type t on t.oid=a.atttypid left join pg_attrdef d on d.adrelid=a.attrelid and d.adnum=a.attnum where a.attrelid=c.oid and a.attnum>0 and not a.attisdropped)) order by c.relname) from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='synapse' and c.relkind='r'),
'constraints',(select jsonb_agg(jsonb_build_object('table',c.conrelid::regclass::text,'name',c.conname,'type',c.contype,'definition',pg_get_constraintdef(c.oid,true)) order by c.conrelid::regclass::text,c.conname) from pg_constraint c join pg_namespace n on n.oid=c.connamespace where n.nspname='synapse' and c.contype<>'n'),
'indexes',(select jsonb_agg(jsonb_build_object('name',i.relname,'definition',pg_get_indexdef(i.oid)) order by i.relname) from pg_class i join pg_namespace n on n.oid=i.relnamespace where n.nspname='synapse' and i.relkind='i' and not exists(select 1 from pg_constraint c where c.conindid=i.oid)),
'functions',(select jsonb_agg(jsonb_build_object('name',p.proname,'identity',p.oid::regprocedure::text,'owner',pg_get_userbyid(p.proowner),'definition',pg_get_functiondef(p.oid)) order by p.proname) from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='synapse'),
'triggers',(select jsonb_agg(jsonb_build_object('name',t.tgname,'table',c.relname,'enabled',t.tgenabled,'definition',pg_get_triggerdef(t.oid,true)) order by c.relname,t.tgname) from pg_trigger t join pg_class c on c.oid=t.tgrelid join pg_namespace n on n.oid=c.relnamespace where n.nspname='synapse' and not t.tgisinternal),
'policies',(select jsonb_agg(to_jsonb(p) order by p.tablename,p.policyname) from pg_policies p where p.schemaname='synapse'),
'views',(select jsonb_agg(jsonb_build_object('name',c.relname,'owner',pg_get_userbyid(c.relowner),'options',c.reloptions,'definition',pg_get_viewdef(c.oid,true)) order by c.relname) from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='synapse' and c.relkind='v'),
'sequences',(select jsonb_agg(jsonb_build_object('name',c.relname,'type',format_type(s.seqtypid,null),'start',s.seqstart::text,'increment',s.seqincrement::text,'min',s.seqmin::text,'max',s.seqmax::text,'cache',s.seqcache::text,'cycle',s.seqcycle,'owned_by',(select format('%I.%I.%I',n2.nspname,c2.relname,a.attname) from pg_depend d join pg_class c2 on c2.oid=d.refobjid join pg_namespace n2 on n2.oid=c2.relnamespace join pg_attribute a on a.attrelid=c2.oid and a.attnum=d.refobjsubid where d.classid='pg_class'::regclass and d.objid=c.oid and d.refobjsubid>0 and d.deptype in('a','i')),'identity',(exists(select 1 from pg_depend d where d.classid='pg_class'::regclass and d.objid=c.oid and d.deptype='i'))) order by c.relname) from pg_sequence s join pg_class c on c.oid=s.seqrelid join pg_namespace n on n.oid=c.relnamespace where n.nspname='synapse'),
'grants',(select jsonb_agg(to_jsonb(g) order by g.kind,g.object,g.grantee,g.privilege) from (
select 'schema' kind,quote_ident(n.nspname) object,case when acl.grantee=0 then 'PUBLIC' else pg_get_userbyid(acl.grantee) end grantee,acl.privilege_type privilege,acl.is_grantable grantable from pg_namespace n cross join lateral aclexplode(coalesce(n.nspacl,acldefault('n',n.nspowner))) acl where n.nspname='synapse'
union all select case when c.relkind='S' then 'sequence' else 'table' end,format('%I.%I',n.nspname,c.relname),case when acl.grantee=0 then 'PUBLIC' else pg_get_userbyid(acl.grantee) end,acl.privilege_type,acl.is_grantable from pg_class c join pg_namespace n on n.oid=c.relnamespace cross join lateral aclexplode(coalesce(c.relacl,acldefault(case when c.relkind='S' then 'S'::"char" else 'r'::"char" end,c.relowner))) acl where n.nspname='synapse' and c.relkind in('r','v','S')
union all select 'function',p.oid::regprocedure::text,case when acl.grantee=0 then 'PUBLIC' else pg_get_userbyid(acl.grantee) end,acl.privilege_type,acl.is_grantable from pg_proc p join pg_namespace n on n.oid=p.pronamespace cross join lateral aclexplode(coalesce(p.proacl,acldefault('f',p.proowner))) acl where n.nspname='synapse')g),
'default_acls',(select jsonb_agg(jsonb_build_object('owner',pg_get_userbyid(d.defaclrole),'schema',n.nspname,'type',d.defaclobjtype,'acl',d.defaclacl::text)) from pg_default_acl d left join pg_namespace n on n.oid=d.defaclnamespace where n.nspname='synapse'),
'reference_data',jsonb_build_object('roles',(select jsonb_agg(to_jsonb(t) order by role_code) from synapse.roles t),'permissions',(select jsonb_agg(to_jsonb(t) order by permission_code) from synapse.permissions t),'role_permissions',(select jsonb_agg(to_jsonb(t) order by role_id,permission_id) from synapse.role_permissions t),'case_statuses',(select jsonb_agg(to_jsonb(t) order by sort_order) from synapse.case_statuses t),'case_relationship_types',(select jsonb_agg(to_jsonb(t) order by relationship_type) from synapse.case_relationship_types t)),
'extensions',(select jsonb_agg(jsonb_build_object('name',e.extname,'schema',n.nspname,'version',e.extversion) order by e.extname) from pg_extension e join pg_namespace n on n.oid=e.extnamespace),
'counts',jsonb_build_object('auth_users',(select count(*) from auth.users),'users',(select count(*) from synapse.users),'cases',(select count(*) from synapse.cases),'buckets',(select count(*) from storage.buckets),'institutions',(select count(*) from synapse.institutions),'bureaus',(select count(*) from synapse.bureaus))
) as baseline;
